# @@ Newton's method with a given derivative
def newton(f, df, x, tol, max_iter) {
    for k to max_iter {
        step = py_div_f(f(x), df(x))
        x -= step
        print("  step ", fmt((py_int(k + 1)) + 0.0, "d"), ": x = ", fmt(x, ".12f"), sep="")
        if abs(step) < tol {
            return x
        }
    }
    stop("RuntimeError: Newton did not converge")
}
# @@ the square root of 2
def _lam17(x) {
    return x * x - 2.0
}
def _lam17_2(x) {
    return 2.0 * x
}
root2 = newton(_lam17, _lam17_2, 1.0, 1e-12, 50)
print("sqrt(2) ~", fmt(root2, ".12f"))
# @@ where cos(x) = x
def _lam21(x) {
    return cos(py_mtrig(x)) - x
}
def _lam21_2(x) {
    return -sin(py_mtrig(x)) - 1.0
}
dottie = newton(_lam21, _lam21_2, 1.0, 1e-12, 50)
print("cos(x) = x at", fmt(dottie, ".12f"))
# @@ checks
if not (abs(root2 - py_msqrt(2.0)) < 1e-12) {
    stop("AssertionError")
}
if not (abs(cos(py_mtrig(dottie)) - dottie) < 1e-12) {
    stop("AssertionError")
}
